@DatabaseRepositoryAdapter public class MybatisRootAuthenticationRepository implements RootBootstrapStateRepository,RootRecoveryGrantRepository{private final IamAuthenticationDao dao;public MybatisRootAuthenticationRepository(IamAuthenticationDao dao){this.dao=dao;}public RootBootstrapState find(){Map<String,Object>r=dao.findRootBootstrapState();return r==null?RootBootstrapState.required():new RootBootstrapState(RootBootstrapState.Status.valueOf(string(r,"status")),bool(r,"passwordConfigured"),bool(r,"mfaConfigured"),bool(r,"tenantCreated"),bool(r,"tenantAdminCreated"),Optional.ofNullable(instant(r,"completedAt")),longValue(r,"version"));}public RootBootstrapState save(RootBootstrapState s,long expected){Map<String,Object>r=new HashMap<>();r.put("status",s.status().name());r.put("passwordConfigured",s.passwordConfigured());r.put("mfaConfigured",s.mfaConfigured());r.put("tenantCreated",s.tenantCreated());r.put("tenantAdminCreated",s.tenantAdminCreated());r.put("completedAt",s.completedAt().orElse(null));r.put("version",s.version());if(dao.updateRootBootstrapState(r,expected)!=1)throw new IamOptimisticLockException("RootBootstrapState","ROOT",expected);return s;}public Optional<RootRecoveryGrant>find(String id){return Optional.ofNullable(dao.findRootRecoveryGrant(id)).map(this::grant);}public RootRecoveryGrant save(RootRecoveryGrant g,long expected){int n=expected==0?dao.insertRootRecoveryGrant(row(g)):dao.updateRootRecoveryGrant(row(g),expected);if(n!=1)throw new IamOptimisticLockException("RootRecoveryGrant",g.grantId(),expected);return g;}private RootRecoveryGrant grant(Map<String,Object>r){return new RootRecoveryGrant(string(r,"grantId"),string(r,"initiatorId"),string(r,"approverId"),string(r,"grantHash"),instant(r,"issuedAt"),instant(r,"expiresAt"),Optional.ofNullable(instant(r,"consumedAt")),RootRecoveryGrant.Status.valueOf(string(r,"status")),longValue(r,"version"));}private Map<String,Object>row(RootRecoveryGrant g){Map<String,Object>r=new HashMap<>();r.put("grantId",g.grantId());r.put("initiatorId",g.initiatorId());r.put("approverId",g.approverId());r.put("grantHash",g.grantHash());r.put("issuedAt",g.issuedAt());r.put("expiresAt",g.expiresAt());r.put("consumedAt",g.consumedAt().orElse(null));r.put("status",g.status().name());r.put("version",g.version());return r;}}
